+namespace sv_0acbf2fb485141ae936190ce49660b33.Services;
+
+/// <summary>
+/// Scoped service that polls for low-stock alerts and notifies all subscribers.
+/// Each circuit has its own instance ensuring user isolation.
+/// </summary>
+public sealed class InventoryAlertService : IDisposable
+{
+    private readonly WarehouseStateService _warehouseState;
+    private PeriodicTimer? _timer;
+    private CancellationTokenSource? _cts;
+    private int _subscriberCount;
+
+    public int CurrentLowStockCount { get; private set; }
+
+    /// <summary>
+    /// Fired when new alert data arrives. All subscribed components should re-render.
+    /// </summary>
+    public event Action? OnAlertDataChanged;
+
+    public InventoryAlertService(WarehouseStateService warehouseState)
+    {
+        _warehouseState = warehouseState;
+        _warehouseState.OnWarehouseChanged += HandleWarehouseChanged;
+    }
+
+    /// <summary>
+    /// Simulates a database query returning a random low-stock count for the warehouse.
+    /// </summary>
+    public Task<int> GetLowStockCountAsync(string warehouseId)
+    {
+        return Task.FromResult(Random.Shared.Next(0, 16));
+    }
+
+    /// <summary>
+    /// Starts polling if not already running. Multiple components can subscribe;
+    /// polling stops only when all unsubscribe.
+    /// </summary>
+    public void StartPolling()
+    {
+        _subscriberCount++;
+        if (_subscriberCount == 1)
+        {
+            _cts = new CancellationTokenSource();
+            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
+            _ = PollLoopAsync(_cts.Token);
+        }
+    }
+
+    /// <summary>
+    /// Decrements subscriber count. Stops polling when no subscribers remain.
+    /// </summary>
+    public void StopPolling()
+    {
+        _subscriberCount = Math.Max(0, _subscriberCount - 1);
+        if (_subscriberCount == 0)
+        {
+            CancelPolling();
+        }
+    }
+
+    private async Task PollLoopAsync(CancellationToken ct)
+    {
+        // Fire an immediate poll on start
+        await RefreshAsync();
+
+        while (!ct.IsCancellationRequested)
+        {
+            try
+            {
+                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
+                    break;
+                await RefreshAsync();
+            }
+            catch (OperationCanceledException)
+            {
+                break;
+            }
+        }
+    }
+
+    private async Task RefreshAsync()
+    {
+        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
+        OnAlertDataChanged?.Invoke();
+    }
+
+    private void HandleWarehouseChanged()
+    {
+        // When warehouse changes, immediately refresh if polling is active
+        if (_subscriberCount > 0)
+        {
+            _ = RefreshAsync();
+        }
+    }
+
+    private void CancelPolling()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = null;
+        _timer?.Dispose();
+        _timer = null;
+    }
+
+    public void Dispose()
+    {
+        _warehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
+        CancelPolling();
+        OnAlertDataChanged = null;
+    }
+}
+

