@using sv_0acbf2fb485141ae936190ce49660b33.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select"><strong>Current Warehouse:</strong></label>
    <select id="warehouse-select" class="form-select form-select-sm"
            @onchange="OnWarehouseSelected" value="@WarehouseState.SelectedWarehouseId">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += StateHasChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= StateHasChanged;
    }
}

