@page "/dashboard"
@rendermode InteractiveServer
@using sv_0acbf2fb485141ae936190ce49660b33.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="dashboard-info">
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">Selected Warehouse</h5>
            <p class="card-text">
                <strong>@GetWarehouseName()</strong>
                <br />
                <small class="text-muted">ID: @WarehouseState.SelectedWarehouseId</small>
            </p>
        </div>
    </div>

    <div class="card mb-3 @(AlertService.CurrentLowStockCount > 5 ? "border-danger" : "border-warning")">
        <div class="card-body">
            <h5 class="card-title">Low Stock Alerts</h5>
            <p class="card-text display-4">@AlertService.CurrentLowStockCount</p>
            <p class="card-text">
                <small class="text-muted">
                    Items below minimum levels — polling every 10 seconds
                </small>
            </p>
        </div>
    </div>

    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">Polling Status</h5>
            <p class="card-text">
                <span class="badge bg-success">Active</span>
                Last updated: @_lastUpdated.ToString("HH:mm:ss")
            </p>
        </div>
    </div>
</div>

@code {
    private DateTime _lastUpdated = DateTime.Now;

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += OnStateChanged;
        AlertService.OnAlertDataChanged += OnAlertChanged;
        AlertService.StartPolling();
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void OnAlertChanged()
    {
        _lastUpdated = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    private string GetWarehouseName()
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.SelectedWarehouseId).Name
            ?? "Unknown";
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= OnStateChanged;
        AlertService.OnAlertDataChanged -= OnAlertChanged;
        AlertService.StopPolling();
    }
}

